python3 -I -c "
import json
def body(ch, ascii):
    p={'amount':'99999.99','payee_firm_uuid':'8b2e4c71-0d3a-4f6e-b1c9-5a7d2e9f4c10','description':ch*500}
    return len(json.dumps({'payer_firm_uuid':'3f1c9a2e-7b4d-4c1e-9a55-2d8e6f0b7c41','payments':[p]*1000},ensure_ascii=ascii,separators=(',',':')).encode())
for name,ch,a in [('2-byte e-acute raw','é',False),('3-byte CJK raw','中',False),('4-byte emoji raw','😀',False),('emoji as \\\\u escapes','😀',True)]:
    print(f'{name}: {body(ch,a)/1e6:.2f} MB')
"

